WITH flattened AS (SELECT id, plan, currency, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_limits) e AS tier_value) SELECT plan, currency, tier_value, PERCENT_RANK() OVER (ORDER BY tier_value DESC NULLS LAST) AS tier_value_percent_rank, DENSE_RANK() OVER (PARTITION BY plan, currency ORDER BY tier_value NULLS FIRST) AS tier_value_dense_rank, PERCENT_RANK() OVER (ORDER BY tier_value NULLS LAST) AS tier_value_percent_rank_2, DENSE_RANK() OVER (PARTITION BY currency ORDER BY tier_value DESC) AS tier_value_dense_rank_2, SUM(tier_value) OVER (PARTITION BY plan) AS plan_sum_tier_value FROM flattened;
